export async function* readText(response: Response) {
  if (!response.ok || !response.body) throw new Error('스트림 시작 실패');
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      yield value;
    }
  } finally { await reader.cancel().catch(() => {}); reader.releaseLock(); }
}
// 이 예시는 text/plain 스트림용이며 SSE에는 별도 프레임 파서가 필요합니다.

type Snippet = { id: string; text: string; tenantId: string; url: string };
export function allowedContext(rows: Snippet[], tenantId: string) {
  return rows.filter(row => row.tenantId === tenantId).slice(0, 6)
    .map(row => ({ sourceId: row.id, text: row.text, url: row.url }));
}
// 실제 DB 검색에도 같은 권한 조건을 적용합니다. 모델이 권한을 판단하지 않습니다.

export function splitParagraphs(text: string, maxChars: number) {
  if (maxChars < 1) throw new Error('양수 길이가 필요합니다.');
  const chunks: string[] = [];
  const paragraphs = text.replaceAll(String.fromCharCode(13), '')
    .split(String.fromCharCode(10, 10));
  for (const paragraph of paragraphs) {
    for (let offset = 0; offset < paragraph.length; offset += maxChars)
      chunks.push(paragraph.slice(offset, offset + maxChars));
  }
  return chunks;
}
// 문자 수는 토큰 수와 다르므로 제공자의 입력 한도도 별도로 확인합니다.

type Extracted = { reference: string; quantity: number | null };
export function validateExtracted(value: unknown): Extracted {
  if (!value || typeof value !== 'object') throw new Error('객체가 필요합니다.');
  const item = value as Record<string, unknown>;
  if (typeof item.reference !== 'string' ||
      !(item.quantity === null || (typeof item.quantity === 'number'
      && Number.isSafeInteger(item.quantity) && item.quantity >= 0)))
    throw new Error('추출 스키마와 맞지 않습니다.');
  return { reference: item.reference, quantity: item.quantity as number | null };
}

type Approval = { planVersion: string; actorId: string; expiresAt: number };
export function approved(a: Approval, version: string, actorId: string, now: number) {
  return a.planVersion === version && a.actorId === actorId && now < a.expiresAt;
}
// 실행 서버가 권한·작업 인자·중복 키를 재검증하고 일회성 승인을 소비합니다.

export function budgetRemaining(limit: number, used: number, reserved: number) {
  for (const n of [limit, used, reserved])
    if (!Number.isSafeInteger(n) || n < 0) throw new Error('잘못된 사용량');
  return Math.max(0, limit - used - reserved);
}
